import React, { useState, useEffect } from 'react';
import { api } from '../services/api';

interface ParkingArea {
  id: string;
  name: string;
  location: string;
  totalSlots: number;
  availableSlots: number;
  status: 'active' | 'maintenance' | 'full';
}

const ParkingAreas: React.FC = () => {
  const [areas, setAreas] = useState<ParkingArea[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    location: '',
    totalSlots: '',
  });

  useEffect(() => {
    fetchParkingAreas();
  }, []);

  const fetchParkingAreas = async () => {
    try {
      // Mock data - Replace with actual API call
      const mockData: ParkingArea[] = [
        { id: '1', name: 'Main Gate Parking', location: 'Near Main Gate', totalSlots: 50, availableSlots: 15, status: 'active' },
        { id: '2', name: 'Library Parking', location: 'Behind Library', totalSlots: 30, availableSlots: 0, status: 'full' },
        { id: '3', name: 'Sports Complex', location: 'Near Sports Complex', totalSlots: 40, availableSlots: 25, status: 'active' },
        { id: '4', name: 'Faculty Parking', location: 'Faculty Block A', totalSlots: 20, availableSlots: 5, status: 'active' },
        { id: '5', name: 'Hostel Parking', location: 'Boys Hostel', totalSlots: 60, availableSlots: 60, status: 'maintenance' },
      ];
      setAreas(mockData);
      
      // Actual API call (uncomment when backend is ready):
      // const response = await api.getParkingAreas();
      // if (response.success && response.data) {
      //   setAreas(response.data);
      // }
    } catch (error) {
      console.error('Failed to fetch parking areas:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    try {
      // Mock API call
      const newArea: ParkingArea = {
        id: Date.now().toString(),
        name: formData.name,
        location: formData.location,
        totalSlots: parseInt(formData.totalSlots),
        availableSlots: parseInt(formData.totalSlots),
        status: 'active',
      };
      
      setAreas([...areas, newArea]);
      
      // Actual API call (uncomment when backend is ready):
      // const response = await api.addParkingArea(formData);
      // if (response.success) {
      //   fetchParkingAreas(); // Refresh list
      // }
      
      setShowForm(false);
      setFormData({ name: '', location: '', totalSlots: '' });
      alert('Parking area added successfully!');
    } catch (error) {
      console.error('Failed to add parking area:', error);
      alert('Failed to add parking area');
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return '#10b981';
      case 'maintenance': return '#f59e0b';
      case 'full': return '#ef4444';
      default: return '#8892b0';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'active': return 'Active';
      case 'maintenance': return 'Maintenance';
      case 'full': return 'Full';
      default: return 'Unknown';
    }
  };

  return (
    <div className="container" style={{ padding: '40px 20px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px' }}>
        <div>
          <h1 style={{ fontSize: '36px', marginBottom: '10px' }}>Parking Areas</h1>
          <p style={{ color: '#8892b0', fontSize: '16px' }}>
            Manage parking zones and monitor slot availability
          </p>
        </div>
        <button
          className="btn btn-primary"
          onClick={() => setShowForm(!showForm)}
          style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
        >
          <span>+</span> Add New Area
        </button>
      </div>

      {/* Add Parking Area Form */}
      {showForm && (
        <div className="card" style={{ marginBottom: '40px' }}>
          <h3 style={{ fontSize: '20px', marginBottom: '20px', color: '#64ffda' }}>
            Add New Parking Area
          </h3>
          <form onSubmit={handleSubmit} style={{ display: 'grid', gap: '20px' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div>
                <label style={styles.label}>Area Name</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  placeholder="e.g., Main Gate Parking"
                  style={styles.input}
                  required
                />
              </div>
              <div>
                <label style={styles.label}>Location</label>
                <input
                  type="text"
                  name="location"
                  value={formData.location}
                  onChange={handleInputChange}
                  placeholder="e.g., Near Main Gate"
                  style={styles.input}
                  required
                />
              </div>
            </div>
            <div style={{ maxWidth: '300px' }}>
              <label style={styles.label}>Total Slots</label>
              <input
                type="number"
                name="totalSlots"
                value={formData.totalSlots}
                onChange={handleInputChange}
                placeholder="e.g., 50"
                min="1"
                style={styles.input}
                required
              />
            </div>
            <div style={{ display: 'flex', gap: '15px' }}>
              <button type="submit" className="btn btn-primary">
                Create Area
              </button>
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setShowForm(false)}
              >
                Cancel
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Parking Areas Grid */}
      {loading ? (
        <div style={{ textAlign: 'center', padding: '60px' }}>
          <div style={{ color: '#8892b0' }}>Loading parking areas...</div>
        </div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: '24px' }}>
          {areas.map((area) => (
            <div key={area.id} className="card">
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '20px' }}>
                <div>
                  <h3 style={{ fontSize: '20px', marginBottom: '5px', color: '#e6f1ff' }}>
                    {area.name}
                  </h3>
                  <p style={{ color: '#8892b0', fontSize: '14px' }}>
                    <span style={{ marginRight: '10px' }}>📍</span>
                    {area.location}
                  </p>
                </div>
                <div style={{
                  padding: '6px 12px',
                  background: getStatusColor(area.status) + '20',
                  border: `1px solid ${getStatusColor(area.status)}`,
                  borderRadius: '20px',
                  color: getStatusColor(area.status),
                  fontSize: '12px',
                  fontWeight: '600' as const,
                }}>
                  {getStatusText(area.status)}
                </div>
              </div>

              <div style={{ marginBottom: '20px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
                  <span style={{ color: '#8892b0', fontSize: '14px' }}>Slot Usage</span>
                  <span style={{ color: '#e6f1ff', fontSize: '14px' }}>
                    {area.totalSlots - area.availableSlots} / {area.totalSlots}
                  </span>
                </div>
                <div style={{
                  height: '8px',
                  background: 'rgba(10, 25, 47, 0.5)',
                  borderRadius: '4px',
                  overflow: 'hidden',
                }}>
                  <div style={{
                    width: `${((area.totalSlots - area.availableSlots) / area.totalSlots) * 100}%`,
                    height: '100%',
                    background: 'linear-gradient(90deg, #64ffda, #57cbff)',
                    borderRadius: '4px',
                  }} />
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
                <div style={styles.statCard}>
                  <div style={{ color: '#8892b0', fontSize: '12px' }}>Total Slots</div>
                  <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#64ffda' }}>
                    {area.totalSlots}
                  </div>
                </div>
                <div style={styles.statCard}>
                  <div style={{ color: '#8892b0', fontSize: '12px' }}>Available</div>
                  <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#10b981' }}>
                    {area.availableSlots}
                  </div>
                </div>
              </div>

              <div style={{ display: 'flex', gap: '10px', marginTop: '20px', flexWrap: 'wrap' }}>
                <button className="btn btn-secondary" style={{ padding: '8px 16px', fontSize: '13px' }}>
                  Edit
                </button>
                <button className="btn btn-secondary" style={{ padding: '8px 16px', fontSize: '13px' }}>
                  View Slots
                </button>
                <button className="btn btn-secondary" style={{ padding: '8px 16px', fontSize: '13px' }}>
                  {area.status === 'active' ? 'Disable' : 'Activate'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

const styles = {
  label: {
    display: 'block',
    fontSize: '14px',
    color: '#8892b0',
    marginBottom: '8px',
    fontWeight: '500' as const,
  },
  input: {
    width: '100%',
    padding: '12px 16px',
    background: 'rgba(10, 25, 47, 0.5)',
    border: '1px solid rgba(100, 255, 218, 0.2)',
    borderRadius: '8px',
    color: '#e6f1ff',
    fontSize: '14px',
  },
  statCard: {
    background: 'rgba(10, 25, 47, 0.3)',
    border: '1px solid rgba(100, 255, 218, 0.1)',
    borderRadius: '8px',
    padding: '15px',
    textAlign: 'center' as const,
  },
};

export default ParkingAreas;
